TOTAL_PROCESSED = 0


def collect_new_skus(batch, seen=[]):
    global TOTAL_PROCESSED
    new = []
    for sku in batch:
        TOTAL_PROCESSED += 1
        if sku not in seen:
            seen.append(sku)
            new.append(sku)
    return {'new': new, 'seen': seen, 'processed': TOTAL_PROCESSED}


