def collect_new_skus(batch, seen=None):
    previous = list(seen) if seen is not None else []
    known = set(previous)
    new = []
    for sku in batch:
        if sku not in known:
            known.add(sku)
            new.append(sku)
    return {'new': new, 'seen': previous + new, 'processed': len(batch)}


